"""Aligns genomeSnippet against testAgainst with Needleman-Wunsch
"""

from needleman_wunsch import align, match_line

WIDTH = 60

# Salmonella DNA from the dsa page
genomeSnippet = ""
testAgainst = ""


def main() -> None:
    """Prints the score and the alignment, WIDTH letters per line"""
    score, a, b = align(genomeSnippet, testAgainst)
    matches = match_line(a, b)

    print("Score:", score)
    print("Matches:", matches.count("|"), "of", len(a), "columns")
    print()
    for start in range(0, len(a), WIDTH):
        print("snippet ", a[start:start + WIDTH])
        print("        ", matches[start:start + WIDTH])
        print("against ", b[start:start + WIDTH])
        print()


if __name__ == "__main__":
    main()
